-module(io_options).
-moduledoc "io's options, terminal size, write and password functions (plan 21 LIB63).".
-export([main/1]).

main(_) ->
    standard_io(),
    standard_error(),
    files(),
    io:format("io_options: ok~n").

standard_io() ->
    show(getopts, io:getopts()),
    show(getopts_user, io:getopts(user) =:= io:getopts()),
    show(columns, io:columns()),
    show(rows, io:rows(user)),
    show(setopts_binary, io:setopts([binary])),
    show(binary_line, io:get_line("")),
    show(binary_chars, io:get_chars("", 3)),
    show(setopts_list, io:setopts(standard_io, [list, {encoding, utf8}])),
    show(list_line, io:get_line("")),
    show(unicode_chars, io:get_chars("", 2)),
    show(rest_line, io:get_line("")),
    show(setopts_latin1, io:setopts([latin1])),
    show(latin1_line, io:get_line("")),
    show(getopts_latin1, proplists:get_value(encoding, io:getopts())),
    show(setopts_unicode, io:setopts([unicode, {echo, true}, {log, none}])),
    show(echo, proplists:get_value(echo, io:getopts())),
    show(setopts_first_wins, io:setopts([binary, list])),
    show(first_binary, proplists:get_value(binary, io:getopts())),
    ok = io:setopts([list]),
    show(setopts_bad, io:setopts([bogus])),
    show(setopts_line_history, io:setopts([{line_history, true}])),
    show(setopts_bad_encoding, io:setopts([{encoding, utf16}])),
    show(setopts_utf8_atom, io:setopts([utf8])),
    show(get_password, io:get_password()),
    show(fread, io:fread("", "~d")),
    show(eof_line, io:get_line("")),
    show(printable_range, io:printable_range()),
    show(write, io:write({a, "b", 1.0, <<"c">>, [1 | 2]})),
    io:nl(),
    show(write_device, io:write(standard_io, [x])),
    io:nl(),
    show(request_getopts, io:request(standard_io, getopts) =:= io:getopts()).

standard_error() ->
    show(error_getopts, io:getopts(standard_error)),
    show(error_columns, io:columns(standard_error)),
    show(error_setopts, io:setopts(standard_error, [{onlcr, true}, utf8])),
    show(error_getopts, io:getopts(standard_error)),
    show(error_setopts_bad, io:setopts(standard_error, [binary])),
    show(error_setopts_back, io:setopts(standard_error, [{onlcr, false}, {encoding, unicode}])),
    show(error_write, io:write(standard_error, ok)).

files() ->
    Name = "io_options.txt",
    {ok, F} = file:open(Name, [write, read]),
    show(file_getopts, io:getopts(F)),
    show(file_columns, io:columns(F)),
    show(file_password, io:get_password(F)),
    show(file_setopts, io:setopts(F, [binary])),
    show(file_getopts, io:getopts(F)),
    show(file_setopts_unicode, io:setopts(F, [list, {encoding, utf8}])),
    show(file_getopts, io:getopts(F)),
    show(file_setopts_utf16, io:setopts(F, [{encoding, utf16}])),
    show(file_getopts, io:getopts(F)),
    show(file_setopts_bad_encoding, io:setopts(F, [{encoding, ebcdic}])),
    show(file_setopts_bad, io:setopts(F, [{echo, true}])),
    ok = io:setopts(F, [{encoding, unicode}]),
    show(file_put_unicode, io:put_chars(F, [16#3b1, 16#3b2, $\n, $x, $\n])),
    {ok, 0} = file:position(F, bof),
    show(file_get_line, io:get_line(F, "")),
    show(file_get_chars, io:get_chars(F, "", 1)),
    ok = io:setopts(F, [binary]),
    {ok, 0} = file:position(F, bof),
    show(file_binary_line, io:get_line(F, "")),
    show(file_binary_chars, io:get_chars(F, "", 2)),
    show(file_eof, io:get_chars(F, "", 2)),
    ok = file:close(F),
    {ok, L} = file:open(Name, [read, {encoding, utf8}]),
    show(opened_getopts, io:getopts(L)),
    show(opened_line, io:get_line(L, "")),
    show(opened_read, file:read(L, 1)),
    show(opened_read_line, file:read_line(L)),
    ok = file:close(L),
    {ok, R} = file:open(Name, [read, binary, {encoding, utf8}]),
    show(opened_read_wide, file:read(R, 1)),
    show(opened_after_wide, file:read(R, 1)),
    file:close(R),
    show(open_bad_encoding, file:open(Name, [read, {encoding, ebcdic}])),
    {ok, W} = file:open(Name, [write]),
    show(latin1_put, io:put_chars(W, [16#e9])),
    ok = file:close(W),
    show(latin1_bytes, file:read_file(Name)),
    ok = file:delete(Name).

show(Label, Value) -> io:format("~p ~w~n", [Label, Value]).
